remarks.para:
 Once the controller is configured, the easiest way to update your application is to use
 one of the 
 methods. These methods use the controller's built-in dialogs to guide the user through the
 entire update process. Note that since the user might choose to update the application
 from these methods, the application might shut down before they return. Handle
 the  event to perform work needed before the application
 shuts down.

 using System;
 using System.Windows.Forms;
 using Kjs.AppLife.Update.Controller;

 class UpdatableForm : Form {
   [STAThread]
   static void Main() {
     Application.EnableVisualStyles();
     Application.SetCompatibleTextRenderingDefault(false);
     Application.Run(new UpdatableForm());
   }

   private UpdateController mController;

   public UpdatableForm() {
     Button updateButton = new Button();
     updateButton.Text = "Update!";
     updateButton.Click += new EventHandler(updateButton_Click);
     this.Controls.Add(updateButton);

     this.mController = new UpdateController();
	    // These settings do not represent a real update server.
     this.mController.UpdateLocation = "my-update-server/updates";
     this.mController.ApplicationId = new Guid("01234567-89AB-CDEF-0123-456789ABCDEF");
     this.mController.PublicKeyToken = "<RSAKeyValue><Modulus>25yO48pjp1EWrE/kCAfjtXpX" +
	      "1q/s1iS0stCFqPSJ0IkftbieP80gBitULM2cdR6kMEde/bZ/zwESOCqo2us6aLnKHam5B3o3g94jYf" +
	      "jYWC4KE/fm7qDZx0MkVhmwSfqCZXQdouOmfQVe7Uf48Qg/R3x45alcdDHUAYoNVK8Hn88=</Modulu" +
	      "s><Exponent>AQAB</Exponent></RSAKeyValue>";
   }

   void updateButton_Click(object sender, EventArgs e) {
     this.mController.UpdateInteractive(this);
   }
 }


 Imports Kjs.AppLife.Update.Controller

 Public Class UpdatableForm
   Dim mController As UpdateController

   Public Sub New()
     Dim updateButton As New Button()
     updateButton.Text = "Update!"
     AddHandler updateButton.Click, AddressOf updateButton_Click
     Me.Controls.Add(updateButton)

     Me.mController = New UpdateController()
     ' These settings do not represent a real update server.
     Me.mController.UpdateLocation = "my-update-server/updates"
     Me.mController.ApplicationId = New Guid("01234567-89AB-CDEF-0123-456789ABCDEF")
     Me.mController.PublicKeyToken = "<RSAKeyValue><Modulus>25yO48pjp1EWrE/kCAfjtXpX" & _
      "1q/s1iS0stCFqPSJ0IkftbieP80gBitULM2cdR6kMEde/bZ/zwESOCqo2us6aLnKHam5B3o3g94jYf" & _
      "jYWC4KE/fm7qDZx0MkVhmwSfqCZXQdouOmfQVe7Uf48Qg/R3x45alcdDHUAYoNVK8Hn88=</Modulu" & _
      "s><Exponent>AQAB</Exponent></RSAKeyValue>"
   End Sub

   Private Sub updateButton_Click(ByVal sender As Object, ByVal e As EventArgs)
     Me.mController.UpdateInteractive(Me)
   End Sub
 End Class

